        /// <summary>True when cell (row, col) of the 8x8 marker (border included, row 0 at the top) is white.</summary>
        public static bool White(int id, int row, int col)
        {
            if (row <= 0 || row >= 7 || col <= 0 || col >= 7) return false;
            int k = (row - 1) * 6 + (col - 1);
            return ((Inner[id % Count] >> (35 - k)) & 1UL) != 0;
        }
    }
